mapper.select:

		/*getOrderPO*/
      SELECT  #{st_doc_type} ||TO_CHAR(SYSDATE,'YY')||LPAD(DECODE(YEAR, TO_CHAR(SYSDATE,'YYYY'), CUR_NO, 1),6,0) AS ORDERNO 
        FROM ICOMSQMT         
       WHERE COMPANY  = #{st_company}    
         AND DOC_TYPE = #{st_doc_type}

mapper.update:

UPDATE ICOMSQMT                  
   SET YEAR   = DECODE(YEAR,TO_CHAR(SYSDATE,'YYYY'), YEAR, TO_CHAR(SYSDATE,'YYYY')) ,    
       CUR_NO = DECODE(YEAR,TO_CHAR(SYSDATE,'YYYY'),CUR_NO+1,1)
WHERE COMPANY =#{st_company} 
  AND DOC_TYPE=#{st_doc_type}
